<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount, onMounted } from 'vue';
import { Form, Head, Link } from '@inertiajs/vue3';
import InputError from '@/components/InputError.vue';
import { login } from '@/routes';
import { store } from '@/routes/register';

defineProps<{ passwordRules: string }>();
defineOptions({ layout: { title: 'Tạo tài khoản', description: 'Đăng ký tài khoản để bắt đầu mua sắm tại TechStore.' } });
const showBenefits=ref(false);const isMounted=ref(false);const email=ref('');const password=ref('');const passwordConfirmation=ref('');const showPassword=ref(false);const showConfirmation=ref(false);const emailChecking=ref(false);const googleLinked=ref(false);const emailChecked=ref(false);const emailExists=ref(false);const emailAvailable=ref(false);let emailCheckTimer:ReturnType<typeof setTimeout>|null=null;let emailCheckController:AbortController|null=null;
const passwordReady=computed(()=>password.value.length>=8);const passwordsMatch=computed(()=>passwordConfirmation.value.length>0&&password.value===passwordConfirmation.value);const passwordsMismatch=computed(()=>passwordConfirmation.value.length>0&&password.value!==passwordConfirmation.value);const emailValid=computed(()=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()));
function checkEmailAvailability(){if(emailCheckTimer)clearTimeout(emailCheckTimer);emailCheckController?.abort();emailChecked.value=false;emailExists.value=false;emailAvailable.value=false;googleLinked.value=false;emailChecking.value=false;const value=email.value.trim().toLowerCase();if(!emailValid.value)return;emailCheckTimer=setTimeout(async()=>{const controller=new AbortController();emailCheckController=controller;emailChecking.value=true;try{const response=await fetch(`/auth/check-email?email=${encodeURIComponent(value)}`,{headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},signal:controller.signal});if(!response.ok)throw new Error('email-check-failed');const data=await response.json();if(email.value.trim().toLowerCase()!==value)return;emailExists.value=Boolean(data.exists);emailAvailable.value=Boolean(data.available);googleLinked.value=Boolean(data.google_linked);emailChecked.value=true}catch(error){if(error instanceof DOMException&&error.name==='AbortError')return;emailChecked.value=false}finally{if(emailCheckController===controller)emailChecking.value=false}},250)}
watch(email,checkEmailAvailability);const closeBenefits=()=>{showBenefits.value=false};onMounted(()=>{isMounted.value=true});onBeforeUnmount(()=>{if(emailCheckTimer)clearTimeout(emailCheckTimer);emailCheckController?.abort()});
</script>
<template>
<Head title="Đăng ký"/><button type="button" class="register-benefit" @click="showBenefits=true"><span class="register-benefit-icon"><i class="bi bi-gift-fill"/></span><span class="register-benefit-content"><span class="register-benefit-title">Ưu đãi thành viên mới</span><span class="register-benefit-text">Đăng ký hôm nay để nhận thông tin khuyến mãi sớm nhất.</span></span><span class="register-benefit-arrow"><i class="bi bi-chevron-right"/></span></button><Teleport v-if="isMounted" to="body"><Transition name="benefit-modal"><div v-if="showBenefits" class="benefit-modal-backdrop" @click.self="closeBenefits"><section class="benefit-modal" role="dialog" aria-modal="true"><button type="button" class="benefit-modal-close" @click="closeBenefits"><i class="bi bi-x-lg"/></button><div class="benefit-modal-hero"><div class="benefit-modal-gift"><i class="bi bi-gift-fill"/></div><div><span class="benefit-modal-eyebrow">TECHSTORE MEMBER</span><h2>Đặc quyền thành viên</h2><p>Đăng ký tài khoản để mở khóa trải nghiệm mua sắm đầy đủ hơn tại TechStore.</p></div></div><div class="benefit-list"><article class="benefit-item"><span class="benefit-item-icon blue"><i class="bi bi-ticket-perforated-fill"/></span><div><strong>Ưu đãi & mã giảm giá</strong><p>Nhận thông tin chương trình ưu đãi và mã giảm giá dành cho thành viên.</p></div></article><article class="benefit-item"><span class="benefit-item-icon purple"><i class="bi bi-bell-fill"/></span><div><strong>Cập nhật sản phẩm mới</strong><p>Dễ dàng theo dõi sản phẩm mới và chương trình nổi bật.</p></div></article><article class="benefit-item"><span class="benefit-item-icon orange"><i class="bi bi-receipt-cutoff"/></span><div><strong>Quản lý đơn hàng</strong><p>Xem lịch sử mua hàng và trạng thái giao hàng trong tài khoản.</p></div></article><article class="benefit-item"><span class="benefit-item-icon green"><i class="bi bi-shield-check"/></span><div><strong>Tài khoản an toàn</strong><p>Bảo vệ tài khoản với các tùy chọn bảo mật của TechStore.</p></div></article></div><div class="benefit-modal-footer"><span><i class="bi bi-stars"/> Nhiều tiện ích hơn khi trở thành thành viên</span><button type="button" class="benefit-modal-button" @click="closeBenefits">Đã hiểu <i class="bi bi-arrow-right"/></button></div></section></div></Transition></Teleport>
<Form v-bind="store.form()" :reset-on-success="['password','password_confirmation']" v-slot="{errors,processing}" class="register-form"><div class="register-field"><label for="name" class="register-label">Họ và tên</label><div class="register-input-wrap"><i class="bi bi-person"/><input id="name" type="text" name="name" class="register-input" required autofocus autocomplete="name" placeholder="Nguyễn Văn A"/></div><InputError :message="errors.name"/></div><div class="register-field"><label for="email" class="register-label">Email</label><div :class="['register-input-wrap',{'is-valid':emailChecked&&emailAvailable,'is-info':emailChecked&&googleLinked,'is-invalid':emailChecked&&!emailAvailable}]"><i class="bi bi-envelope"/><input id="email" v-model="email" type="email" name="email" class="register-input" required autocomplete="email" placeholder="email@example.com"/><span v-if="emailChecking" class="spinner-border spinner-border-sm text-primary"/><i v-else-if="emailChecked&&googleLinked" class="bi bi-google field-status google"/><i v-else-if="emailChecked&&emailAvailable" class="bi bi-check-circle-fill field-status success"/><i v-else-if="emailChecked&&!emailAvailable" class="bi bi-exclamation-circle-fill field-status danger"/></div><div v-if="emailChecked&&!emailAvailable&&!googleLinked" class="email-exists-notice"><i class="bi bi-exclamation-circle-fill"/><span>Email này đã được sử dụng. Vui lòng dùng Email khác.</span></div><div v-else-if="emailChecked&&googleLinked" class="google-account-notice"><div class="google-notice-icon"><i class="bi bi-google"/></div><div><strong>Email này đã liên kết với Google</strong><p>Bạn có thể <a href="/auth/google">đăng nhập bằng Google</a> hoặc tiếp tục tạo mật khẩu.</p></div></div><InputError :message="errors.email"/></div><div class="register-field"><label for="password" class="register-label">Mật khẩu</label><div :class="['register-input-wrap',{'is-valid':passwordReady,'is-invalid':password&&!passwordReady}]"><i class="bi bi-lock"/><input id="password" v-model="password" :type="showPassword?'text':'password'" name="password" class="register-input" required autocomplete="new-password" placeholder="Nhập mật khẩu" :passwordrules="passwordRules"/><button type="button" class="password-toggle" @click="showPassword=!showPassword"><i :class="showPassword?'bi bi-eye-slash':'bi bi-eye'"/></button></div><div v-if="password" class="password-strength"><div class="strength-head"><span>{{passwordReady?'Mật khẩu đạt yêu cầu':'Mật khẩu còn thiếu'}}</span><b>{{passwordReady?'Đạt':'Chưa đạt'}}</b></div><div class="strength-bars"><span :class="{filled:passwordReady}"/><span :class="{filled:passwordReady}"/><span :class="{filled:passwordReady}"/><span :class="{filled:passwordReady}"/><span :class="{filled:passwordReady}"/></div><div class="password-rules"><span :class="{passed:passwordReady}"><i :class="passwordReady?'bi bi-check-circle-fill':'bi bi-circle'"/> Ít nhất 8 ký tự</span></div></div><InputError :message="errors.password"/></div><div class="register-field"><label for="password_confirmation" class="register-label">Xác nhận mật khẩu</label><div :class="['register-input-wrap',{'is-valid':passwordsMatch,'is-invalid':passwordsMismatch}]"><i class="bi bi-shield-check"/><input id="password_confirmation" v-model="passwordConfirmation" :type="showConfirmation?'text':'password'" name="password_confirmation" class="register-input" required autocomplete="new-password" placeholder="Nhập lại mật khẩu" :passwordrules="passwordRules"/><button type="button" class="password-toggle" @click="showConfirmation=!showConfirmation"><i :class="showConfirmation?'bi bi-eye-slash':'bi bi-eye'"/></button></div><div v-if="passwordsMatch" class="match-message success-text"><i class="bi bi-check-circle-fill"/> Mật khẩu trùng khớp</div><div v-else-if="passwordsMismatch" class="match-message danger-text"><i class="bi bi-exclamation-circle-fill"/> Mật khẩu nhập lại không trùng khớp</div><InputError :message="errors.password_confirmation"/></div><div class="register-password-hint"><i class="bi bi-shield-check"/><span>Mật khẩu chỉ cần ít nhất 8 ký tự.</span></div><button type="submit" class="register-submit" :disabled="processing||!passwordReady||!passwordsMatch||!emailValid||(emailChecked&&!emailAvailable)"><span v-if="processing" class="spinner-border spinner-border-sm"/><i v-else class="bi bi-person-plus-fill"/>{{processing?'Đang tạo tài khoản...':'Tạo tài khoản'}}<i v-if="!processing" class="bi bi-arrow-right"/></button></Form><div class="register-terms">Bằng việc đăng ký, bạn đồng ý với các điều khoản sử dụng của TechStore.</div><div class="register-bottom"><span>Đã có tài khoản?</span><Link :href="login()">Đăng nhập ngay <i class="bi bi-arrow-right"/></Link></div></template>
