f;font-size:10px}.google-account-notice p{margin:3px 0 0;color:#6f7d91;font-size:9px;line-height:1.45}.google-account-notice a{color:#2563eb;text-decoration:none;font-weight:700}.password-strength{margin-top:7px;padding:10px 11px;border:1px solid #e8edf3;border-radius:11px;background:#f8fafc}.strength-head{display:flex;justify-content:space-between;color:#64748b;font-size:9px}.strength-head b{color:#2563eb;font-weight:850}.strength-bars{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-top:7px}.strength-bars span{height:4px;border-radius:99px;background:#e2e8f0}.strength-bars span.filled{background:#2563eb}.password-rules{margin-top:7px;color:#94a3b8;font-size:9px}.password-rules span{display:flex;align-items:center;gap:4px}.password-rules span.passed{color:#16a34a}.match-message{margin-top:6px;font-size:9px;font-weight:650}.success-text{color:#16a34a}.danger-text{color:#dc2626}.register-password-hint{display:flex;align-items:center;gap:7px;margin-top:-4px;color:#8a95a5;font-size:10px;line-height:1.45}.register-password-hint i{color:#2563eb;font-size:12px}
